                    "nc006_accepted_library":"../NC-006/accepted_library.json",
                    "nc001_canonical_isa":"../NC-001/canonical_isa.py",
                    "nc005_checkpoint_manifest":"../NC-005/checkpoint_manifest.json"}.items():
